from pathlib import Path
import json,shutil,hashlib,html
root=Path.cwd();out=Path(__file__).resolve().parents[1];dest=root/'public/reviews/small-cylinder-profiles-2026-10-31';dest.mkdir(parents=True,exist_ok=True)
def asset(rel,name=None):
 p=out/rel;n=name or p.name;shutil.copy2(p,dest/n);return n
profiles=[('3.3 ml clear','glass-3.3-profile-v4','renders/glass-3.3-v2.png','source-review/01-merged.png','cylinder-3.3ml-clear-12mm-finemist'),('4 ml clear','glass-4-profile-v4','renders/glass-4-v2.png','source-review/02-merged.png','cylinder-4ml-clear-12mm-finemist'),('5 ml clear','glass-5-clear-measured-v19','renders/glass-5-clear-profile-v4.png','source-review/08-merged.png','cylinder-5ml-clear-13-415-finemist'),('5 ml cobalt','glass-5-cobalt-measured-v19','renders/glass-5-cobalt-profile-v4.png','source-review/09-merged.png','cylinder-5ml-cobalt-blue-13-415-finemist')]
cards=[];models=[]
photo_ref=asset('user-photos/inspection-previews/IMG_6841.png','5ml-upright-reference.png')
for label,stem,old,source,slug in profiles:
 current=asset('renders/'+stem+'.png');previous=asset(old);photo=asset(source);meta=json.loads((out/'renders'/f'{stem}.json').read_text());models.append({'label':label,'scene':str(out/'renders'/f'{stem}.blend'),'render':str(out/'renders'/f'{stem}.png'),'sha256':hashlib.sha256((out/'renders'/f'{stem}.png').read_bytes()).hexdigest(),**meta})
 cards.append(f'<section><h2>{label}</h2><p><a href="/products/{slug}?cap=black">Open interactive product page →</a></p><div class="compare"><figure><a href="{photo}"><img src="{photo}"></a><figcaption>Original product photograph</figcaption></figure><figure><img src="{previous}"><figcaption>Previous body render</figcaption></figure><figure><img src="{current}"><figcaption>Corrected Blender body · local review</figcaption></figure></div></section>')
rows=[]
small=json.loads((root/'public/local-kits/small-sprayers-2026-10-31/kits.json').read_text())['rows']
for sku,k in small.items():rows.append({'sku':sku,'body':k['familyId'],'defects':['body crop omitted the neck','overweight heel in first model candidate','inconsistent fitment crops','duplicate overcap choices']+(['3 ml / 3.3 ml naming conflict'] if '3ml' in sku else []),'corrections':['closed Blender glass with complete neck and lighter heel','published external envelope preserved','black and white head photographs cropped consistently','one clear cover master','approved scale and foot unchanged','product-page only'],'status':'local visual review; concealed finish remains inferred'})
