for r in checks:rows.append({'sku':r['sku'],'body':'cylinder-5ml-13-415 '+r['glass'],'defects':['prior nominal 17 mm body did not match user caliper measurements','neck and shoulder silhouette did not match the physical bottle; shoulder datum and internal depth were estimated','rim and thread walls needed measurement-based reconstruction','unmeasured 12 mm plain rim and flared opening made the neck read too wide']+(['bent assembled dip tube'] if r['tubeReplaced'] else []),'corrections':['53.23 mm overall height; nominal 17.45 mm gently bowed body','40.10 mm shoulder to base; 48.80 mm internal depth; 4.43 mm inner floor','12.00 mm root and 12.60 mm thread-crest diameters','1.80 mm lip wall and 2.64 mm wall at thread crests; inferred uniform 7.32 mm bore and derived 10.92 mm plain rim','short smooth shoulder and rounded threads referenced to upright and side-view physical photographs; real lower ring and gap retained','one shared geometry for clear and cobalt','approved scale targets and closure anchors preserved']+(['centered straight 1.1 mm OD tube; full tube in exploded view'] if r['tubeReplaced'] else []),'status':'local visual review against user caliper dimensions; uniform bore inferred; plain rim derived as 10.92 mm'})
report={'status':'LOCAL REVIEW ONLY. No originals replaced, no upload or production changes. Not a catalog-wide sign-off.','scope':'3.3 ml and 4 ml clear 12 mm fine mist; 5 ml Cylinder clear/cobalt 13-415','skus':rows,'models':models,'orientationPolicy':'Catalog base stays down and neck stays up. Inverted IMG_6848/6849 are base-detail references only.','limitations':['The exact 3.3/4 ml original PSD photos have the sprayer on. Their concealed 12 mm finish geometry is inferred, not manufacturer-verified.','Five ml dimensions now follow Jordan caliper measurements. A uniform 7.32 mm opening is inferred from the measured 12.60 mm crest and 2.64 mm wall; the 1.80 mm rim wall gives a 10.92 mm plain rim. Unthreaded neck lands follow that diameter and the supplied clear reference. This is not a manufacturing tolerance drawing.','The legacy technical drawing, label-fit diagram and PDF link are omitted only for these local measured-body previews because they still carry the earlier dimensions. They require a separate measured drawing update before release.','The product data still carries legacy 5 ml dimensions; local callouts and the tech sheet now show 53.23 mm height and 17.45 mm nominal diameter. No backend record was changed.','This local review does not approve unrelated product families, checkout or redirects.'],'sources':[{'url':'https://www.bestbottles.com/product/Sample-Promotional-Decant-Spray-clear-glass-vial-Black-Sprayer-3ml','use':'3.3 ml description, 14 mm diameter, 37 mm bare height'},{'url':'https://www.bestbottles.com/product/Sample-Promotional-Decant-Spray-clear-glass-vial-Black-Sprayer-4ml','use':'14 mm diameter, 49 mm bare height'},{'url':'https://www.bestbottles.com/product/cylinder-design-5-ml-glass-bottle-short-black-cap','use':'Historical nominal reference only. Superseded by Jordan physical measurements for this model.'}]}
report['clearGlassAppearance']={'version':'v19','change':'Restored graduated neutral-grey reflection cards, replaced short strips with a broad diffuser and full-height feathered highlights from Jordan’s clear 5 ml example, and restored the lit studio background through clear glass. Approved clear v16 and cobalt v9 appearance settings are retained while both share the v19 measured neck/body geometry. Camera, crop, scale and closures remain unchanged.','previous':'renders/glass-5-clear-measured-v9.png','current':'renders/glass-5-clear-measured-v19.png'}
report['verification']=json.loads((out/'five-measured-verification.json').read_text())
report['photoOrientation']=json.loads((out/'user-photos/orientation-review.json').read_text())
report['fiveMlUserMeasurements']=json.loads((out/'five-user-measurements.json').read_text())
(out/'profile-review-report.json').write_text(json.dumps(report,indent=2));shutil.copy2(out/'profile-review-report.json',dest/'report.json')
lines=['# Small Cylinder profile review','',report['status'],'','## Corrections','',f'{len(rows)} exact SKUs use the local review: 4 small sprayers and 71 five-millilitre configurations.','', 'The 3.3/4 ml bottles remain product-page only. The 5 ml body is shared with the builder. Approved framing stays at 28%, 32.5%, and 36.5% shoulder-to-foot with the foot at 91%.','','## Source limits','']+['- '+x for x in report['limitations']]+['','## Files','','- `renders/*profile-v4.blend` and `renders/*measured-v19.blend`: editable native copies','- `renders/*profile-v4.png` and `renders/*measured-v19.png`: isolated glass exports; `mechanism-5-measured-v6.png` is the measured tube','- `user-photos/orientation-review.json`: orientation classification for all ten physical reference photos','- `five-measured-verification.json`: dimension, shared geometry, orientation and camera-clip checks','- `source-review/sources.json`: original PSD paths, hashes and layers','- `before-*.png`, `before-profile-v4/`, `after-*.png`: browser comparisons','- `profile-review-report.json`: per-SKU defects, fixes and provenance','- `browser-checks.json`, `five-browser-checks.json`, `five-layout-checks.json`: QA evidence']
(out/'README.md').write_text('\n'.join(lines)+'\n')
sourceLinks=''.join(f'<li><a href="{x["url"]}">{html.escape(x["use"])}</a></li>' for x in report['sources'])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Small Cylinder body review</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f3ef;color:#222;font:16px/1.5 system-ui,sans-serif}main{max-width:1350px;margin:auto;padding:40px 24px}h1{font-size:34px;font-weight:500;letter-spacing:-1px}h2{font-size:24px;font-weight:500}a{color:#785d30}section{padding:26px 0;border-top:1px solid #d8d2c7}.compare{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.compare figure{margin:0;background:#efede8;padding:16px;text-align:center}.compare img{width:100%;height:360px;object-fit:contain}.compare figcaption{margin:16px 0 0;font-size:13px}p{max-width:900px}.note{padding:20px;background:#e9e4da}details{margin-top:30px}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:10px;text-align:left;border-bottom:1px solid #ccc;vertical-align:top}@media(max-width:700px){main{padding:24px 14px}.compare{gap:6px}.compare figure{padding:6px}.compare img{height:220px}.compare figcaption{font-size:11px}h1{font-size:28px}}</style><main><p>BEST BOTTLES · OCTOBER 31, 2026 · LOCAL REVIEW</p><h1>3.3, 4 and 5 ml Cylinder glass bodies</h1><p>Corrected Blender profiles, compared with the original product photographs and previous body renders. Open each product page to inspect sidecar, cap-on and exploded views.</p><p class="note">The profile comparisons below use equal image heights for inspection. Interactive pages retain the approved catalog scale: 28% / 32.5% / 36.5%, with the glass foot at 91%. These are review candidates. The 3.3/4 ml concealed necks remain inferred. The 5 ml body follows Jordan’s caliper measurements, with the uniform-opening assumption and derived rim diameter documented in the report.</p>'''+f'<section><h2>5 ml physical reference and orientation</h2><p>The upright photo below guides the neck and shoulder. IMG_6848 and IMG_6849 show the bottle upside down and are used only for base details. All renders keep the base down and neck up. The lower neck ring and gap visible in the physical bottle are retained.</p><a href="{photo_ref}"><img src="{photo_ref}" style="width:100%;max-width:600px" alt="Upright cobalt 5 ml bottle, user reference"></a></section>'+''.join(cards)+f'<details><summary>Per-SKU defect and correction record ({len(rows)} SKUs)</summary><p><a href="report.json">Download full report and source provenance</a></p><table><tr><th>SKU</th><th>Defects</th><th>Corrections</th></tr>'+''.join('<tr><td>'+html.escape(r['sku'])+'</td><td>'+html.escape('; '.join(r['defects']))+'</td><td>'+html.escape('; '.join(r['corrections']))+'</td></tr>' for r in rows)+'</table></details><details><summary>Manufacturer references</summary><ul>'+sourceLinks+'</ul></details><p>Originals preserved. No production changes or uploads.</p></main></html>'
(dest/'index.html').write_text(page)
print(dest/'index.html');print(len(rows),'SKU records')
